    <section className="exchange"><h3>Tournament JSON</h3><label htmlFor="tournament-json">Tournament JSON</label><textarea className="control" id="tournament-json" rows={6} value={json} onChange={(e) => setJson(e.currentTarget.value)} /><div className="tournament-actions"><button className="control" onClick={() => { setJson(encodeTournament({ tournament, snapshot: active ? controller.exportSnapshot() : null })); setNotice('"'Tournament exported.'); }}>Export tournament</button><button className=\"control\" onClick={load} aria-describedby=\"tournament-notice\">Load tournament</button></div><p id=\"tournament-notice\">{notice}</p></section>
