    if (active && !wasPaused.current) controller.setPaused(false);
  }
  function load(): void {
    const result = decodeTournament(json);
    if (!result.document) {
      setNotice(result.error);
      setAnnouncement(result.error);
      return;
    }
    const doc = result.document;
    confirm(() => {
      if (doc.snapshot) controller.loadSnapshot(doc.snapshot);
      setTournament(doc.tournament);
      setNotice('Tournament loaded.');
      setAnnouncement('Tournament loaded.');
      setDialog(null);
    });
  }
  const player = match && tournament ? match.players[playerIndex(match)] : null;
  return (
    <>
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      {!tournament && (
        <section className="tournament-setup">
          <div>
            <label htmlFor="players">Players</label>{' '}
            <select
              className="control"
              id="players"
              value={count}
              onChange={(e) => setCount(Number(e.currentTarget.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
          </div>
          <div className="player-fields">
            {names.slice(0, count).map((name, index) => (
              <div key={index}>
                <label htmlFor={`player-${index}`}>Player {index + 1}</label>
                <input
                  className="control"
                  id={`player-${index}`}
                  value={name}
                  onChange={(e) => {
                    const next = [...names];
                    next[index] = e.currentTarget.value;
                    setNames(next);
                  }}
                />
              </div>
            ))}
          </div>
          <div className="tournament-actions">
            <button className="control" onClick={start}>
              Start tournament
            </button>
            <button className="control" onClick={back}>
              Back to game
            </button>
          </div>
        </section>
      )}
      {tournament && (
        <section className="tournament-current">
          {tournament.phase !== 'complete' && (
            <>
              <p>Round: {roundName(tournament.names.length, tournament.current)}</p>
              <p>Now playing: {player == null ? '' : tournament.names[player]}</p>
            </>
          )}
          {tournament.phase === 'ready' && (
            <button className="control" onClick={begin}>
              Start turn
            </button>
          )}
          {tournament.phase === 'turnDone' && (
            <button
              className="control"
              onClick={() => {
                setTournament({ ...tournament, phase: 'ready' });
                setAnnouncement(`Now playing: ${tournament.names[match?.players[1] ?? 0]}`);
              }}
            >
              Next turn
            </button>
          )}
          {tournament.phase === 'matchDone' && (
            <button
              className="control"
              onClick={() => {
                const current = tournament.current + 1;
                setTournament({ ...tournament, current, phase: 'ready' });
                setAnnouncement(
                  `Now playing: ${tournament.names[tournament.matches[current]?.players[0] ?? 0]}`,
